import { z } from 'zod';
import { toolSchema } from './tools.js';
import { completionEventSchema } from './completion-event.js';
import { REASONING_BUDGET_MAX } from './llamacpp-config.js';
export { completionStatsSchema } from './completion-event.js';
/**
 * Tool-call output dialect. Auto-detected from the model name; pass via
 * `completion({ toolDialect })` to override.
 *
 * Expected raw model output per dialect:
 * - `"hermes"`:   `<tool_call>{"name":"get_weather","arguments":{"city":"Tokyo"}}</tool_call>`
 * - `"pythonic"`: `[get_weather(city="Tokyo")]` (optionally `<|tool_call_start|>...<|tool_call_end|>`-wrapped)
 * - `"json"`:     `{"name":"get_weather","arguments":{"city":"Tokyo"}}` or `{"tool_calls":[{"name":"...","arguments":{...}}]}`
 * - `"harmony"`:  `<|channel|>commentary to=functions.get_weather <|constrain|>json<|message|>{"city":"Tokyo"}<|call|>`
 * - `"qwen35"`:   `<tool_call><function=NAME><parameter=KEY>VALUE</parameter></function></tool_call>`
 * - `"gemma4"`:   `<|tool_call>call:NAME{key:<|"|>val<|"|>,...}<tool_call|>`
 * - `"dsml"`:     `<｜DSML｜tool_calls><｜DSML｜invoke name="NAME"><｜DSML｜parameter name="KEY" string="true">VALUE</｜DSML｜parameter></｜DSML｜invoke></｜DSML｜tool_calls>`
 *                 (DeepSeek Markup Language, emitted by DeepSeek V3.2 / V4)
 */
export const toolDialectSchema = z.enum([
    'hermes',
    'pythonic',
    'json',
    'harmony',
    'qwen35',
    'gemma4',
    'dsml'
]);
export const attachmentSchema = z.object({
    path: z
        .string()
        .describe('Absolute or SDK-resolvable path to the attachment file (e.g., image for multimodal models).')
});
const kvCacheSchema = z.union([
    z.boolean(),
    z.string().min(1, 'KV cache key cannot be empty string')
]);
export const generationParamsSchema = z
    .object({
    temp: z.number().optional().describe('Sampling temperature (typically 0–2).'),
    top_p: z.number().optional().describe('Top-p (nucleus) sampling cutoff (0–1).'),
    top_k: z.number().optional().describe('Top-k sampling — keep only the top K tokens.'),
    predict: z
        .number()
        .optional()
        .describe('Max tokens to predict. `-1` = until stop token, `-2` = until context filled.'),
    seed: z.number().optional().describe('Random seed for reproducibility.'),
    frequency_penalty: z
        .number()
        .optional()
        .describe('Penalty applied to tokens based on frequency so far.'),
    presence_penalty: z
        .number()
        .optional()
        .describe('Penalty applied to tokens that have already appeared.'),
    repeat_penalty: z.number().optional().describe('Penalty applied to repeated tokens.'),
    reasoning_budget: z
        .number()
        .int()
        .min(-1)
        .max(REASONING_BUDGET_MAX)
        .optional()
        .describe("Per-request reasoning channel budget. `-1` keeps the model's reasoning channel on; `0` disables it for this request; any positive integer caps the reasoning channel at that many tokens. Equivalent to the load-time `reasoning_budget` config but scoped to a single `run()` call; the prior value is restored afterwards."),
    remove_thinking_from_context: z
        .boolean()
        .optional()
        .describe('When the model emits a reasoning block during generation (e.g. `<think>...</think>` for the Qwen3 family, `<|channel>thought ... <channel|>` for Gemma 4), drop those tokens from the KV cache at end-of-generation so subsequent turns do not accumulate reasoning history. Defaults to `false`, except the Qwen3 reasoning family (Qwen3, Qwen3.5, Qwen3.6, including MoE variants), which defaults to `true`. No-op for models without a recognised reasoning channel. Supported on recurrent / hybrid-SSM models (e.g. Qwen3.5) via a state snapshot and replay when the reasoning close marker is a single token; on such a model with a multi-token close marker, enabling this fails with an error.')
})
    .strict();
const jsonSchemaObjectSchema = z.record(z.string(), z.unknown());
export const responseFormatSchema = z.discriminatedUnion('type', [
    z.object({ type: z.literal('text') }).strict(),
    z.object({ type: z.literal('json_object') }).strict(),
    z
        .object({
        type: z.literal('json_schema'),
        json_schema: z
            .object({
            name: z
                .string()
                .min(1)
                .describe('Schema identifier; OpenAI-compatibility only — not used by the addon.'),
            description: z
                .string()
                .optional()
                .describe('Free-form schema description. Accepted for OpenAI compatibility only — not forwarded to the addon and does not affect generation.'),
            schema: jsonSchemaObjectSchema.describe("JSON Schema the model output must validate against. Forwarded to the addon as-is and converted to GBNF natively by llama.cpp's `json_schema_to_grammar()`."),
            strict: z
                .boolean()
                .optional()
                .describe("Accepted for OpenAI compatibility but does NOT trigger OpenAI's auto-tightening semantics (implicit `additionalProperties: false`, all properties required). The schema is forwarded to the addon verbatim, so callers wanting strict validation must encode it explicitly in `schema`.")
        })
            .strict()
    })
        .strict()
]);
export const completionParamsSchema = z.object({
    history: z
        .array(z.object({
        role: z.string().describe('Message role (e.g., `"user"`, `"assistant"`, `"system"`).'),
        content: z.string().describe('Message content.'),
        attachments: z
            .array(attachmentSchema)
            .optional()
            .describe('Optional file attachments for multimodal models.')
    }))
        .describe('Array of conversation messages sent to the model.'),
    modelId: z.string().describe('The identifier of the model to use for completion.'),
    kvCache: kvCacheSchema
        .optional()
        .describe('KV cache configuration — `true` to auto-generate a cache key from history, a string to use a custom key, or `false`/`undefined` to disable.')
});
const completionClientParamsBaseSchema = completionParamsSchema.extend({
    tools: z
        .array(toolSchema)
        .optional()
        .describe('Optional array of tools (full `Tool` objects or Zod-schema `ToolInput` definitions) the model can call.'),
    stream: z
        .boolean()
        .describe('Whether to stream tokens (`true`) or return the complete response once (`false`).'),
    kvCache: kvCacheSchema.optional(),
    generationParams: generationParamsSchema
        .optional()
        .describe('Optional sampling / generation parameters.'),
    captureThinking: z
        .boolean()
        .optional()
        .describe('When `true`, capture and emit reasoning/thinking deltas separately from content deltas; requires a model that frames its thinking output.'),
    emitRawDeltas: z
        .boolean()
        .optional()
        .describe('When `true`, also emit raw per-token deltas in the event stream in addition to normalized `contentDelta` events.'),
    toolDialect: toolDialectSchema
        .optional()
        .describe("Override auto-detected tool-call dialect. Use when the SDK's name-based detection picks the wrong parser chain for your model."),
    responseFormat: responseFormatSchema
        .optional()
        .describe('Optional structured-output constraint: `text` (default, free-form), `json_object` (any valid JSON), or `json_schema` (output conforms to the provided JSON Schema). Mutually exclusive with `tools`.'),
    requestId: z
        .string()
        .min(1)
        .optional()
        .describe('Stable identifier for this in-flight request, generated by the client at call time (opaque token, UUIDv4 when available). Surfaced on the `CompletionRun` result so callers can target it with `cancel({ requestId })`. Optional on the wire so legacy clients keep working — the server falls back to a server-generated id when the field is missing. Note: cancel-by-requestId only takes effect once the server has begun the request, so a cancel issued in the same tick as `completion()` may arrive before the request is registered.')
});
function refineNoToolsWithStructuredOutput(data, ctx) {
    if (data.responseFormat &&
        data.responseFormat.type !== 'text' &&
        data.tools &&
        data.tools.length > 0) {
        ctx.addIssue({
            code: 'custom',
            message: 'responseFormat (json_object/json_schema) cannot be combined with tools; tools already constrain output via their parameter schema.',
            path: ['responseFormat']
        });
    }
}
export const completionClientParamsSchema = completionClientParamsBaseSchema.superRefine(refineNoToolsWithStructuredOutput);
export const completionStreamRequestSchema = completionClientParamsBaseSchema
    .extend({
    type: z.literal('completionStream')
})
    .superRefine(refineNoToolsWithStructuredOutput);
export const completionStreamResponseSchema = z
    .object({
    type: z.literal('completionStream'),
    done: z.boolean().optional(),
    events: z.array(completionEventSchema)
})
    .strict();
// ============================================
// Worker-orchestrated completion (duplex)
// ============================================
export const completionOrchestrateRequestSchema = completionClientParamsBaseSchema
    .extend({
    type: z.literal('completionOrchestrate'),
    maxToolTurns: z
        .number()
        .int()
        .min(1)
        .max(32)
        .optional()
        .describe('Upper bound on generation turns the worker will run before ending the ' +
        'loop with `stopReason: "maxToolTurns"`. Each turn is one completion ' +
        'pass; a turn that requests tool calls consumes callbacks and starts ' +
        'the next turn. Defaults to 8.')
})
    .superRefine(refineNoToolsWithStructuredOutput);
/**
 * Downstream frame of the orchestrated completion duplex stream. Exactly one
 * payload field is set per frame:
 *
 * - `events` — pass-through of the inner completion turn's events (with
 *   `turn` identifying which generation pass they belong to).
 * - `toolCallback` — the worker is asking the CLIENT to run a tool. The
 *   client executes its registered handler and writes a JSON line
 *   (`toolCallbackResultSchema`) up the request stream. The worker blocks
 *   this run (not the socket) until the matching `callId` arrives.
 * - `done` — terminal frame; the loop ended (final answer produced, error,
 *   cancellation, or the `maxToolTurns` cap).
 *
 * Only a LOCAL worker may emit `toolCallback`: tool handlers execute code on
 * the client machine, so a remote delegate streaming through this shape must
 * never trigger them.
 */
export const completionOrchestrateResponseSchema = z
    .object({
    type: z.literal('completionOrchestrate'),
    turn: z.number().int().nonnegative().optional(),
    events: z.array(completionEventSchema).optional(),
    toolCallback: z
        .object({
        callId: z.string().describe('Correlates the upstream result line to this request.'),
        name: z.string(),
        arguments: z.record(z.string(), z.unknown())
    })
        .optional(),
    done: z.boolean().optional(),
    stopReason: z
        .literal('maxToolTurns')
        .optional()
        .describe('Set on the terminal `done` frame only when the loop stopped because it ' +
        'hit `maxToolTurns` (the model still wanted a tool). Absent on a natural ' +
        'finish, so the caller can tell a truncated run from a completed one.')
})
    .strict();
/**
 * Upstream JSON line the client writes after running a tool callback.
 * Newline-delimited on the duplex request stream, after the initial request
 * payload. `error` reports a handler failure; the worker forwards it to the
 * model as the tool result so the loop can recover or finish.
 */
export const toolCallbackResultSchema = z.object({
    callId: z.string(),
    result: z.unknown().optional(),
    error: z.string().optional()
});
