    cfmSteps: ttsNonNegativeIntegerSchema.optional(),
    cfgRate: z.number().nonnegative().optional(),
    threads: ttsPositiveIntegerSchema.optional(),
    nGpuLayers: ttsIntegerSchema.optional(),
    seed: ttsIntegerSchema.optional()
