    useGPU: z.boolean().optional(),
    outputSampleRate: ttsOutputSampleRateSchema.optional(),
    threads: ttsPositiveInt32Schema.optional(),
    nGpuLayers: ttsInt32Schema.optional(),
    seed: ttsInt32Schema.optional()
